components.css:
.ap-abstract{margin:var(--space-lg) auto var(--space-xl);max-width:var(--measure-column);padding:0 var(--space-lg);border-top:1px solid var(--color-border-default);border-bottom:1px solid var(--color-border-default)}
.ap-abstract h2{font-size:var(--size-h3);line-height:var(--line-tight);text-transform:uppercase;letter-spacing:.1em;margin:var(--space-md) 0 var(--space-sm)}
.ap-abstract p{margin:0 0 var(--space-md);line-height:var(--line-body);color:var(--color-text-secondary)}
